CREATE TABLE effect_jobs(id bigserial PRIMARY KEY,business_key text NOT NULL,revision integer NOT NULL,payload text NOT NULL CHECK(payload='fixed-catalog-v1'),state text NOT NULL DEFAULT 'ready' CHECK(state IN ('ready','leased','effect_started','done','retry_wait','dead_letter')),preflight_ok boolean NOT NULL DEFAULT true,owner text NOT NULL DEFAULT '',token text NOT NULL DEFAULT '',generation bigint NOT NULL DEFAULT 0,attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3),expires timestamptz,available_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(business_key,revision));
CREATE TABLE effect_latches(job_id bigint PRIMARY KEY REFERENCES effect_jobs(id),generation bigint NOT NULL,owner text NOT NULL,token text NOT NULL,status text NOT NULL DEFAULT 'started' CHECK(status IN ('started','done')));
